const http = require('http');
const fs = require('fs');

function dockerGet(path) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    const req = http.request({ socketPath: '/var/run/docker.sock', path, method: 'GET' }, res => {
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        try { resolve(JSON.parse(Buffer.concat(chunks).toString())); }
        catch(e) { resolve(Buffer.concat(chunks).toString()); }
      });
    });
    req.on('error', reject);
    req.end();
  });
}

const containers = await dockerGet('/v1.44/containers/json?all=1');
const lines = containers.map(c => {
  const name = (c.Names[0] || '').replace(/^\//, '');
  return `${name}\t${c.Status}`;
}).join('\n');

let state = {};
try { state = JSON.parse(fs.readFileSync('/mnt/nas/n8n/homelab-state.json', 'utf8')); } catch(e) {}

const incidents = Object.keys(state.incidents || {});
const incidentSummary = incidents.length === 0
  ? 'No active incidents'
  : Object.entries(state.incidents).map(([k,v]) => `${k}: retries=${v.retries} status=${v.status}`).join(', ');

return `CONTAINERS:\n${lines}\n\nINCIDENTS: ${incidentSummary}`;

const http = require('http');

const containerName = query.trim().replace(/[^a-zA-Z0-9_\-\.]/g, '');
if (!containerName) return 'Error: no container name provided';

const logs = await new Promise((resolve, reject) => {
  const chunks = [];
  const req = http.request({
    socketPath: '/var/run/docker.sock',
    path: `/v1.44/containers/${containerName}/logs?stdout=1&stderr=1&tail=30`,
    method: 'GET'
  }, res => {
    if (res.statusCode === 404) { resolve('Container not found: ' + containerName); return; }
    res.on('data', c => chunks.push(c));
    res.on('end', () => {
      const buf = Buffer.concat(chunks);
      let result = '';
      let offset = 0;
      while (offset + 8 <= buf.length) {
        const size = buf.readUInt32BE(offset + 4);
        if (offset + 8 + size > buf.length) break;
        result += buf.slice(offset + 8, offset + 8 + size).toString();
        offset += 8 + size;
      }
      resolve(result || buf.toString());
    });
  });
  req.on('error', reject);
  req.end();
});

return logs || 'No logs';

const http = require('http');

const containerName = query.split('|')[0].trim().replace(/[^a-zA-Z0-9_\-\.]/g, '');
if (!containerName) return 'Error: provide container name';

const result = await new Promise((resolve, reject) => {
  const req = http.request({
    socketPath: '/var/run/docker.sock',
    path: `/v1.44/containers/${containerName}/restart`,
    method: 'POST'
  }, res => {
    if (res.statusCode === 204) resolve(`${containerName} restarted successfully`);
    else if (res.statusCode === 404) resolve(`Container not found: ${containerName}`);
    else resolve(`Unexpected response: HTTP ${res.statusCode}`);
  });
  req.on('error', reject);
  req.end();
});

return result;

const http = require('http');
const https = require('https');
const fs = require('fs');

const results = [];

// Docker info via socket
try {
  const info = await new Promise((resolve) => {
    const chunks = [];
    const req = http.request({ socketPath: '/var/run/docker.sock', path: '/v1.44/info', method: 'GET' }, res => {
      res.on('data', c => chunks.push(c));
      res.on('end', () => { try { resolve(JSON.parse(Buffer.concat(chunks).toString())); } catch(e) { resolve({}); } });
    });
    req.on('error', () => resolve({}));
    req.end();
  });
  results.push(`Docker: ${info.ContainersRunning || '?'} running / ${info.Containers || '?'} total`);
} catch(e) { results.push('Docker: error'); }

// Memory
try {
  const mem = fs.readFileSync('/proc/meminfo', 'utf8');
  const total = parseInt(mem.match(/MemTotal:\s+(\d+)/)?.[1] || 0);
  const avail = parseInt(mem.match(/MemAvailable:\s+(\d+)/)?.[1] || 0);
  const usedPct = Math.round((total - avail) / total * 100);
  results.push(`Memory: ${Math.round(avail/1024)}MB free of ${Math.round(total/1024)}MB (${usedPct}% used)`);
} catch(e) { results.push('Memory: unavailable'); }

// Uptime
try {
  const up = parseFloat(fs.readFileSync('/proc/uptime', 'utf8').split(' ')[0]);
  results.push(`Uptime: ${Math.floor(up/86400)}d ${Math.floor((up%86400)/3600)}h`);
} catch(e) {}

// NAS disk
try {
  const stats = fs.statfsSync('/mnt/nas/n8n');
  const totalGB = Math.round(stats.blocks * stats.bsize / 1e9);
  const freeGB = Math.round(stats.bfree * stats.bsize / 1e9);
  results.push(`NAS: ${freeGB}GB free of ${totalGB}GB`);
} catch(e) { results.push('NAS: not mounted'); }

// Internet - use HTTPS to hostname (raw IP 1.1.1.1 has TLS cert issues inside Docker)
const internetOk = await new Promise((resolve) => {
  const req = https.request(
    { hostname: 'cloudflare.com', path: '/', method: 'HEAD' },
    () => resolve(true)
  );
  req.setTimeout(5000, () => { req.destroy(); resolve(false); });
  req.on('error', () => resolve(false));
  req.end();
});
results.push(`Internet: ${internetOk ? 'reachable' : 'UNREACHABLE'}`);

// Local network - check NPM on same host (router YOUR_ROUTER_IP not reliably routable from Docker bridge)
const npmOk = await new Promise((resolve) => {
  const req = http.request(
    { hostname: 'YOUR_SERVER_IP', port: 81, path: '/', method: 'HEAD' },
    () => resolve(true)
  );
  req.setTimeout(3000, () => { req.destroy(); resolve(false); });
  req.on('error', () => resolve(false));
  req.end();
});
results.push(`Local network (NPM): ${npmOk ? 'reachable' : 'unreachable'}`);

return results.join('\n');

const fs = require('fs');

let state;
try { state = JSON.parse(fs.readFileSync('/mnt/nas/n8n/homelab-state.json', 'utf8')); }
catch(e) { state = { incidents: {} }; }

const action = query.trim().toLowerCase();

if (action === 'list') {
  const keys = Object.keys(state.incidents || {});
  if (keys.length === 0) return 'No active incidents. All monitored services are healthy.';
  return 'Active incidents:\n' + keys.map(k => {
    const i = state.incidents[k];
    return `${k}: retries=${i.retries} status=${i.status} since=${i.firstSeen}`;
  }).join('\n');
}

if (action.startsWith('clear:')) {
  const svc = action.substring(6).trim();
  if (state.incidents && state.incidents[svc]) {
    delete state.incidents[svc];
    fs.writeFileSync('/mnt/nas/n8n/homelab-state.json', JSON.stringify(state, null, 2));
    return `Cleared incident for ${svc}. Monitor will resume retrying next cycle.`;
  }
  return `No active incident for ${svc}. Current: ${Object.keys(state.incidents || {}).join(', ') || 'none'}`;
}

return 'Unknown action. Use "list" or "clear:service_name"';

const https = require('https');

const action = query.trim().toLowerCase();
if (!['status', 'reboot', 'start', 'stop'].includes(action)) {
  return 'Valid actions: status, reboot, start, stop';
}

// Step 1: Authenticate with Proxmox API (self-signed cert, ignore TLS errors)
const postData = 'username=root%40pam&password=YOUR_PASSWORD';
const authResult = await new Promise((resolve) => {
  const chunks = [];
  const req = https.request({
    hostname: 'YOUR_PROXMOX_IP', port: 8006,
    path: '/api2/json/access/ticket', method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'Content-Length': Buffer.byteLength(postData) },
    rejectUnauthorized: false
  }, res => {
    res.on('data', c => chunks.push(c));
    res.on('end', () => { try { resolve(JSON.parse(Buffer.concat(chunks).toString())); } catch(e) { resolve(null); } });
  });
  req.on('error', () => resolve(null));
  req.write(postData);
  req.end();
});

if (!authResult?.data?.ticket) return 'Error: Could not authenticate with Proxmox API';
const ticket = authResult.data.ticket;
const csrfToken = authResult.data.CSRFPreventionToken;
const cookie = `PVEAuthCookie=${ticket}`;

// Step 2: Get current VM 100 status
const statusResult = await new Promise((resolve) => {
  const chunks = [];
  const req = https.request({
    hostname: 'YOUR_PROXMOX_IP', port: 8006,
    path: '/api2/json/nodes/pve/qemu/100/status/current', method: 'GET',
    headers: { 'Cookie': cookie },
    rejectUnauthorized: false
  }, res => {
    res.on('data', c => chunks.push(c));
    res.on('end', () => { try { resolve(JSON.parse(Buffer.concat(chunks).toString())); } catch(e) { resolve(null); } });
  });
  req.on('error', () => resolve(null));
  req.end();
});

const vmStatus = statusResult?.data?.status || 'unknown';

if (action === 'status') {
  const cpu = Math.round((statusResult?.data?.cpu || 0) * 100);
  const memMB = Math.round((statusResult?.data?.mem || 0) / 1024 / 1024);
  const uptime = statusResult?.data?.uptime || 0;
  return `VM 100: ${vmStatus}\nCPU: ${cpu}%\nMemory: ${memMB}MB\nUptime: ${Math.floor(uptime/3600)}h ${Math.floor((uptime%3600)/60)}m`;
}

// Guards
if (action === 'reboot' && vmStatus !== 'running') return `Cannot reboot: VM 100 is ${vmStatus}`;
if (action === 'start' && vmStatus === 'running') return 'VM 100 is already running';
if (action === 'stop' && vmStatus !== 'running') return `VM 100 is already ${vmStatus}`;

// Step 3: Execute action
const result = await new Promise((resolve) => {
  const req = https.request({
    hostname: 'YOUR_PROXMOX_IP', port: 8006,
    path: `/api2/json/nodes/pve/qemu/100/status/${action}`, method: 'POST',
    headers: { 'Cookie': cookie, 'CSRFPreventionToken': csrfToken, 'Content-Length': 0 },
    rejectUnauthorized: false
  }, res => {
    const chunks = [];
    res.on('data', c => chunks.push(c));
    res.on('end', () => resolve(res.statusCode === 200 ? 'success' : `HTTP ${res.statusCode}`));
  });
  req.on('error', () => resolve('connection error'));
  req.end();
});

if (result === 'success') {
  if (action === 'reboot') return 'VM 100 reboot sent to Proxmox. n8n will go offline for ~60 seconds - you will not get a confirmation reply.';
  if (action === 'start') return 'VM 100 start sent. Should be online in ~60 seconds.';
  if (action === 'stop') return 'VM 100 stop sent. All containers and n8n will go offline.';
}
return `Proxmox API returned: ${result}`;
